function reviewInputHash(){return hashText(JSON.stringify({text:el.sourceText.value,background:el.background.value,glossary:effectiveGlossary(),mode:mode(),provider:textProvider()}))}
function markReviewInputChanged(){if(state.reviewSourceHash&&state.reviewSourceHash!==reviewInputHash()&&state.workingText){state.status="stale";state.consistencyDone=false;el.saveStatus.textContent="输入已变化，校订稿需要更新";setRunning(false);renderProse()}queueSave()}
async function saveTask(){
  if(!el.sourceText.value.trim()&&!state.transcriptionDraft.trim()&&!state.workingText&&!el.background.value.trim()){
    el.saveStatus.textContent="尚未保存";
    return;
  }
  const taskId=state.taskId;
  const payload=JSON.stringify(taskData());
  await taskSaveQueue.enqueue({taskId,payload});
}

