function renderResults(){el.originalText.textContent=el.sourceText.value;el.correctedText.value=state.workingText;renderReviewAudio();el.uncertaintyList.replaceChildren();el.changesList.replaceChildren();if(state.uncertainties.length)state.uncertainties.forEach((x,i)=>el.uncertaintyList.append(reviewCard(x,"uncertainty",i)));else{const d=document.createElement("div");d.className="nothing";d.textContent="没有发现需要人工确认的内容。";el.uncertaintyList.append(d)}if(state.changes.length)state.changes.forEach(x=>el.changesList.append(reviewCard(x,"change")));else{const d=document.createElement("div");d.className="nothing";d.textContent="模型没有列出显著修改。";el.changesList.append(d)}el.uncertainCount.textContent=state.uncertainties.length;el.changeCount.textContent=state.changes.length;el.editedState.textContent=state.userEdited?"已包含人工修改":"尚未手动修改";reviewProgress();ensureActiveReview();el.resultSummary.textContent=state.uncertainties.length?`校订完成，有 ${state.uncertainties.length} 处建议核对`:"校订完成，未发现明显疑点";const cost=actualCost();el.usageSummary.textContent=`本次 ${state.usage.total_tokens.toLocaleString()} tokens${cost===null?" · 费用以服务商账单为准":` · 约 ¥${formatCny(cost)}`}`;el.resultCard.classList.remove("empty");el.resultContent.hidden=false;el.undoButton.disabled=!state.undoStack.length;renderProse()}

const proseCompleted=()=>state.proseChunks.map((v,i)=>v?i:null).filter(v=>v!==null);
function addProseUsage(usage){if(usage)for(const key of Object.keys(state.proseUsage))state.proseUsage[key]+=Number(usage[key]||0)}
function proseIsStale(){return!!state.proseText&&(state.proseSourceHash!==hashText(state.workingText)||state.proseGeneratedMode!==state.proseMode)}
function setProseProgress(done,total,hint){const percent=total?Math.round(done/total*100):0;el.proseProgressBar.style.width=`${percent}%`;el.proseProgressValue.textContent=`${percent}%`;el.proseProgressTitle.textContent=done?`已整理 ${done}/${total} 段`:"正在准备论述稿…";el.proseProgressHint.textContent=hint||(done<total?"正在保留全部信息并重组书面表达":"论述稿整理完成")}
function renderProse(){const hasText=!!state.proseText,stale=proseIsStale(),tokens=estimateTokens(state.workingText+el.background.value+effectiveGlossary(state.workingText)),price=PRICE[textModel()]||PRICE["deepseek-flash"],cost=proseActualCost();el.proseMode.value=state.proseMode;el.proseMode.disabled=state.proseRunning;el.proseText.readOnly=state.proseRunning;el.proseEmpty.hidden=hasText;el.proseResult.hidden=!hasText;if(hasText&&document.activeElement!==el.proseText)el.proseText.value=state.proseText;el.copyProse.disabled=!hasText;el.exportProse.disabled=!hasText;el.proseCostEstimate.textContent=!state.workingText?"等待校订稿":textProvider()==="deepseek"?`预计新增约 ¥${formatCny(tokens*(price.input+price.output)/1e6)}，实际以返回 token 为准`:"费用以 OpenAI 账单为准";el.proseUsage.textContent=hasText?`${state.proseUsage.total_tokens.toLocaleString()} tokens${cost===null?" · 费用以服务商账单为准":` · 约 ¥${formatCny(cost)}`}${state.proseUserEdited?" · 已人工编辑":""}`:"";el.proseStateBadge.textContent=state.proseRunning?"整理中":stale?"需更新":state.proseStatus==="completed"?"已生成":state.proseStatus==="failed"?"失败":state.proseStatus==="paused"?"已暂停":"未生成";el.proseButton.textContent=state.proseRunning?"整理中…":state.proseStatus==="failed"||state.proseStatus==="paused"?"继续整理":hasText?"重新生成":"生成论述稿";el.proseButton.disabled=state.proseRunning||state.running||!state.workingText;if(!state.running)el.polishButton.disabled=state.proseRunning;el.proseCancel.hidden=!state.proseRunning;el.proseProgress.hidden=!(state.proseRunning||state.proseStatus==="failed"||state.proseStatus==="paused")}
async function consumeProse(response){
  await readNdjson(response,event=>{
    if(event.type==="start"){state.proseTotalChunks=event.total;setProseProgress(proseCompleted().length,event.total)}
    if(event.type==="stage"){el.proseProgressTitle.textContent=event.stage||"正在整理书面稿";el.proseProgressHint.textContent="已完成内容会持续保存在本机"}
    if(event.type==="plan"){state.prosePlan=event.outline||"";state.proseProtectedFacts=event.protected_facts||[];addProseUsage(event.usage);el.proseProgressHint.textContent=event.reused?"已沿用上次全文结构，继续整理":"全文结构规划完成，正在按统一结构改写";queueSave()}
    if(event.type==="chunk"){state.proseChunks[event.index]=event.written_text;state.proseText=state.proseChunks.join("\n\n");state.proseFailedIndex=null;addProseUsage(event.usage);setProseProgress(proseCompleted().length,event.total);renderProse();queueSave()}
    if(event.type==="final"){state.proseText=event.written_text;addProseUsage(event.usage);renderProse();queueSave()}
    if(event.type==="warning"){addProseUsage(event.usage);el.proseProgressHint.textContent=event.warning||"已保留逐段整理结果"}
    if(event.type==="error"){addProseUsage(event.usage);state.proseFailedIndex=event.index;const error=Error(`第 ${event.index+1} 段整理失败：${event.error}`);error.charged=event.charged;throw error}
  });
}
async function runProse(){if(state.proseRunning||state.running)return;if(!state.workingText.trim())return toast("当前还没有可用的校订稿","error");if(state.status!=="completed")return toast(state.failedIndex!==null?`校订流程尚未完成：第 ${state.failedIndex+1} 段失败，请先点击“继续校订”`:"校订流程尚未完成，请先点击“继续校订”完成剩余步骤","error");const sourceHash=hashText(state.workingText),sameSource=state.proseSourceHash===sourceHash&&state.proseGeneratedMode===state.proseMode,resume=sameSource&&(state.proseStatus==="failed"||state.proseStatus==="paused");if(state.proseText&&!resume&&!proseIsStale()&&!confirm("重新生成会替换当前论述稿，是否继续？"))return;if(!resume){state.proseChunks=[];state.prosePlan="";state.proseProtectedFacts=[];state.proseText="";state.proseTotalChunks=0;state.proseFailedIndex=null;state.proseUsage={prompt_tokens:0,completion_tokens:0,total_tokens:0};state.proseUserEdited=false}state.proseSourceHash=sourceHash;state.proseGeneratedMode=state.proseMode;state.proseAbortController=new AbortController();state.proseRunning=true;state.proseStatus="running";setProseProgress(proseCompleted().length,state.proseTotalChunks||1);renderProse();try{const response=await fetch("/api/rewrite",{method:"POST",headers:{"Content-Type":"application/json"},signal:state.proseAbortController.signal,body:JSON.stringify({textProvider:textProvider(),background:el.background.value,glossary:effectiveGlossary(state.workingText),mode:state.proseMode,text:state.workingText,completedIndices:proseCompleted(),completedChunks:state.proseChunks,savedPlan:resume?state.prosePlan:"",savedProtectedFacts:resume?state.proseProtectedFacts:[]})});await consumeProse(response);state.proseStatus="completed";state.proseFailedIndex=null;setProseProgress(state.proseTotalChunks,state.proseTotalChunks,"论述稿已完成，可继续人工编辑或导出");renderProse();toast("详细论述稿已生成")}catch(error){if(error.name==="AbortError"){state.proseStatus="paused";el.proseProgressTitle.textContent="论述稿整理已暂停";el.proseProgressHint.textContent="已完成段落和进度均已保存，可稍后继续";toast("已暂停论述稿整理")}else{state.proseStatus="failed";el.proseProgressTitle.textContent="论述稿未完成";el.proseProgressHint.textContent=error.message||"整理失败，已保留完成部分";toast(error.message||"论述稿整理失败","error")}}finally{state.proseRunning=false;state.proseAbortController=null;renderProse();queueSave()}}
async function exportProseResult(format){if(!state.proseText)return toast("还没有可导出的论述稿","error");const baseName=`${taskTitle()}-论述稿`;if(format==="txt")download(state.proseText,"txt","text/plain;charset=utf-8",baseName);else if(format==="md")download(`# ${taskTitle()}－论述稿\n\n${state.proseText}\n`,"md","text/markdown;charset=utf-8",baseName);else if(format==="docx"){const response=await fetch("/api/export/docx",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({title:`${taskTitle()}－详细论述稿`,text:state.proseText})});if(!response.ok)return toast((await response.json()).error||"Word 导出失败","error");download(await response.blob(),"docx","application/vnd.openxmlformats-officedocument.wordprocessingml.document",baseName)}$("#proseExportMenu").hidden=true}

async function consume(response){
  await readNdjson(response,event=>{
    if(event.type==="start"){state.totalChunks=event.total;setProgress(completed().length,event.total)}
    if(event.type==="chunk"){state.correctedChunks[event.index]=event.corrected_text;state.uncertainties=state.uncertainties.filter(item=>item._chunkIndex!==event.index);state.uncertainties.push(...event.uncertainties.map(item=>({...item,_chunkIndex:event.index})));state.changes.push(...event.changes);addUsage(event.usage);state.failedIndex=null;state.workingText=state.correctedChunks.join("\n\n");state.modelDraft=state.workingText;reanchor();normalizeUncertainties();setProgress(completed().length,event.total);renderResults();queueSave()}
    if(event.type==="error"){addUsage(event.usage);state.failedIndex=event.index;if(state.workingText)renderResults();const error=Error(`第 ${event.index+1} 段失败：${event.error}`);error.charged=event.charged;throw error}
  });
}
async function consistency(){state.failedStage="consistency";setProgress(state.totalChunks,state.totalChunks,"分段校订完成，正在统一全文术语与人名");const r=await fetch("/api/consistency",{method:"POST",headers:{"Content-Type":"application/json"},signal:state.abortController.signal,body:JSON.stringify({textProvider:textProvider(),background:el.background.value,glossary:effectiveGlossary(state.correctedChunks.join("\n\n")),text:state.correctedChunks.join("\n\n")})}),p=await r.json().catch(()=>({}));if(!r.ok){addUsage(p.usage);if(state.workingText)renderResults();throw Error(p.error||"全文一致性检查失败")}state.workingText=p.corrected_text;state.modelDraft=p.corrected_text;state.changes.push(...(p.changes||[]));const seen=new Set(state.uncertainties.map(x=>`${x.original}|${x.context}`));for(const item of(p.uncertainties||[])){const key=`${item.original}|${item.context}`;if(!seen.has(key)){state.uncertainties.push({...item,_global:true});seen.add(key)}}addUsage(p.usage);state.consistencyDone=true;state.failedStage=null;reanchor();normalizeUncertainties()}
async function run(){if(state.running)return;if(!el.sourceText.value.trim())return toast("请先粘贴转写稿","error");const currentSourceHash=reviewInputHash(),inputChanged=Boolean(state.reviewSourceHash&&state.reviewSourceHash!==currentSourceHash&&state.workingText);if(inputChanged&&!confirm("原稿、语境、术语或校订设置已经变化，旧断点不能安全沿用。是否重新开始校订？"))return;let resume=!inputChanged&&state.status!=="completed"&&state.status!=="stale"&&(completed().length>0||state.failedIndex!==null||state.failedStage||state.status==="paused");if(!resume)resetResults();state.reviewSourceHash=currentSourceHash;state.abortController=new AbortController();state.status="running";setRunning(true);setProgress(completed().length,state.totalChunks||1);try{if(state.failedStage!=="consistency"){const r=await fetch("/api/correct",{method:"POST",headers:{"Content-Type":"application/json"},signal:state.abortController.signal,body:JSON.stringify({textProvider:textProvider(),background:el.background.value,glossary:effectiveGlossary(),mode:mode(),text:el.sourceText.value,completedIndices:completed()})});await consume(r)}if(!state.consistencyDone)await consistency();state.status="completed";state.failedIndex=null;state.failedStage=null;renderResults();toast("校订与全文一致性检查已完成")}catch(error){if(error.name==="AbortError"){state.status="paused";el.progressTitle.textContent="校订已暂停";el.progressHint.textContent="已完成内容和进度均已保存，可点击继续校订";toast("已暂停，可稍后继续")}else{state.status="failed";el.progressTitle.textContent="校订未完成";el.progressHint.textContent=error.message||"校订失败，已保留完成部分";toast(error.message||"校订失败，已保留完成部分","error")}}finally{state.abortController=null;setRunning(false);queueSave()}}

function switchTab(name){$$('.tab').forEach(t=>t.classList.toggle("active",t.dataset.tab===name));$$('.tab-panel').forEach(p=>p.classList.remove("active"));$(`#${name}Panel`).classList.add("active")}
function markdown(){const review=state.uncertainties.map((x,i)=>{const d=state.decisions[i],handled=d?(d.choice==="manual-reviewed"?"已在正文处理":d.choice==="flagged"?`保留内容并插入${UNCERTAINTY_MARK}`:`已采用：${d.replacement}`):"尚未核对";return`${i+1}. 原文：${x.original||"—"}\n   建议：${x.suggestion||"待回听"}\n   处理：${handled}\n   原因：${x.reason||"—"}`}).join("\n");return`# ${taskTitle()}\n\n${state.workingText}\n\n## 待确认与处理记录\n\n${review||"无"}\n`}
function download(content,ext,mime="text/plain;charset=utf-8",baseName=taskTitle()){const blob=content instanceof Blob?content:new Blob([content],{type:mime}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`${baseName.replace(/[\\/:*?"<>|]/g,"-")}-${new Date().toISOString().slice(0,10)}.${ext}`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function exportResult(fmt){if(!state.workingText)return toast("还没有可导出的校订稿","error");if(fmt==="txt")download(state.workingText,"txt");if(fmt==="md")download(markdown(),"md","text/markdown;charset=utf-8");if(fmt==="srt"&&!/\d{2}:\d{2}:\d{2},\d{3}\s+-->/.test(state.workingText))return toast("当前文本不含 SRT 时间戳","error");if(fmt==="vtt"&&!/(WEBVTT|\d{2}:\d{2}:\d{2}\.\d{3}\s+-->)/.test(state.workingText))return toast("当前文本不含 VTT 时间戳","error");if(fmt==="srt"||fmt==="vtt")download(state.workingText,fmt);if(fmt==="docx"){const r=await fetch("/api/export/docx",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({title:taskTitle(),text:state.workingText})});if(!r.ok)return toast((await r.json()).error||"Word 导出失败","error");download(await r.blob(),"docx","application/vnd.openxmlformats-officedocument.wordprocessingml.document")}el.exportMenu.hidden=true}

let selectedAudio=null,activeTranscriptionId=null,transcriptionPoll=null,onlineSettings=null,syncing=false,scrollSyncOffset=0;
let activeReviewIndex=-1,lastPlayingSegment=-1,activeAudio=null,shortcutCaptureAction="",shortcutConfig={...DEFAULT_SHORTCUTS},shortcutDraft={...DEFAULT_SHORTCUTS};
let terminologyLibrary={version:1,groups:[],terms:[]},terminologyDraft=null,terminologyEditorGroupId="general";
function selectedTermGroup(){return terminologyDraft?.groups?.find(group=>group.id===terminologyEditorGroupId)||terminologyDraft?.groups?.[0]}
function renderTaskTerminologyGroups(){if(!el.taskTerminologyGroups)return;const groups=terminologyLibrary.groups||[];if(!state.terminologySnapshot&&!state.terminologyGroupIds.length){state.terminologyGroupIds=groups.filter(group=>group.defaultEnabled).map(group=>group.id);state.terminologySnapshot=createTerminologySnapshot(terminologyLibrary,state.terminologyGroupIds)}el.taskTerminologyGroups.replaceChildren();for(const group of groups){const label=document.createElement("label"),input=document.createElement("input"),span=document.createElement("span");label.className="term-group-chip";input.type="checkbox";input.checked=state.terminologyGroupIds.includes(group.id);span.textContent=group.name;input.onchange=()=>{state.terminologyGroupIds=input.checked?[...new Set([...state.terminologyGroupIds,group.id])]:state.terminologyGroupIds.filter(id=>id!==group.id);refreshTaskTerminologySnapshot({notify:false});updateStats()};label.append(input,span);el.taskTerminologyGroups.append(label)}if(!groups.length){const empty=document.createElement("span");empty.className="terminology-empty";empty.textContent="术语库中还没有分组";el.taskTerminologyGroups.append(empty)}renderTerminologySnapshotState()}
