function acceptTranscription(){const text=el.transcriptionText.value.trim();if(!text)return toast("原始转写稿为空","error");if(el.sourceText.value.trim()&&!confirm("下方已经有原始稿。是否用当前转写稿替换？现有校订结果不会被自动删除。"))return;state.transcriptionDraft=text;el.sourceText.value=text;updateStats();queueSave();toast("已送入人工修订区；可以继续手工修改");el.sourceText.scrollIntoView({behavior:"smooth",block:"center"})}

function currentVersionStage(){if(state.proseText)return"书面稿";if(state.workingText)return"校订稿";if(el.sourceText.value.trim())return"人工修订稿";if(state.transcriptionDraft)return"原始转写稿";return"任务设置"}
async function saveManualVersion(){try{await saveTask()}catch{return toast("当前任务保存失败，未创建手工版本，请检查运行日志后重试","error")}const stage=currentVersionStage(),suggested=`${stage} · ${new Date().toLocaleString()}`,label=prompt("为这个版本命名：",suggested)?.trim();if(label===undefined)return;if(!label)return toast("版本名称不能为空","error");const snapshot={...taskData(),versionStage:stage,versionLabel:label};const r=await fetch(`/api/tasks/${state.taskId}/versions`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(snapshot)}),p=await r.json();if(!r.ok)return toast(p.error||"版本保存失败","error");toast(`已保存版本“${label}”`);if(el.historyDrawer.classList.contains("open"))refreshVersions()}
async function renameVersion(version){const label=prompt("修改版本名称：",version.label||version.stage)?.trim();if(label===undefined)return;if(!label)return toast("版本名称不能为空","error");const r=await fetch(`/api/tasks/${state.taskId}/versions/${version.id}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({label})}),p=await r.json().catch(()=>({}));if(!r.ok)return toast(p.error||"版本重命名失败","error");toast("版本名称已更新");refreshVersions()}
async function deleteVersion(version){if(!confirm(`删除版本“${version.label||version.stage}”？此操作不会删除当前任务。`))return;const r=await fetch(`/api/tasks/${state.taskId}/versions/${version.id}`,{method:"DELETE"}),p=await r.json().catch(()=>({}));if(!r.ok)return toast(p.error||"版本删除失败","error");toast("版本已删除");refreshVersions()}
async function refreshVersions(){const list=$("#versionList");list.replaceChildren();try{const r=await fetch(`/api/tasks/${state.taskId}/versions`),p=await r.json();if(!r.ok)throw Error(p.error||"版本列表读取失败");if(!p.versions?.length){const empty=document.createElement("div");empty.className="nothing";empty.textContent="还没有手动保存的版本。";return list.append(empty)}for(const version of p.versions){const item=document.createElement("div");item.className="history-item version-item";const head=document.createElement("header"),title=document.createElement("strong"),actions=document.createElement("div"),rename=document.createElement("button"),del=document.createElement("button"),meta=document.createElement("small");title.textContent=version.label||version.stage;rename.type=del.type="button";rename.className="version-action";del.className="version-action danger";rename.textContent="重命名";del.textContent="删除";rename.onclick=e=>{e.stopPropagation();renameVersion(version)};del.onclick=e=>{e.stopPropagation();deleteVersion(version)};actions.className="version-actions";actions.append(rename,del);head.append(title,actions);meta.textContent=`${new Date(version.createdAt).toLocaleString()} · ${version.sourceLength} 字`;item.append(head,meta);item.onclick=()=>restoreVersion(version.id);list.append(item)}}catch(error){const empty=document.createElement("div");empty.className="nothing";empty.textContent=error.message||"版本列表读取失败。";list.append(empty)}}
function applyTaskToWorkspace(task,{save=false,message="已恢复任务与校对进度"}={}){state=restoreTaskState(task);activeReviewIndex=-1;activeAudio=null;el.sourceText.value=task.sourceText||"";el.background.value=task.background||"";el.glossary.value=task.glossary||"";updateOnlineTranscriptionProvider(state.transcriptionEngine);if(isAlibabaFileModel(state.transcriptionModel))el.transcriptionModel.value=state.transcriptionModel;$(`input[name=mode][value="${task.mode||"standard"}"]`).checked=true;if(state.workingText){reanchor();normalizeUncertainties()}renderTranscriptionDraft();renderTaskTerminologyGroups();updateStats();if(state.workingText)renderResults();else resetResultView();setRunning(false);if(save)queueSave();openHistory(false);toast(message)}
async function fetchTaskJson(url,label,expectedId){const response=await fetch(url,{cache:"no-store"}),payload=await response.json().catch(()=>({}));if(!response.ok)throw Error(payload.error||`${label}读取失败`);if(!payload||typeof payload!=="object"||!payload.id||(expectedId&&payload.id!==expectedId))throw Error(`${label}数据不完整或与当前任务不匹配`);return payload}
async function restoreVersion(versionId){if(!confirm("恢复这个版本？当前内容仍保留在自动保存记录中，但工作区会切换到所选版本。"))return;const taskId=state.taskId;try{await saveTask();const task=await fetchTaskJson(`/api/tasks/${taskId}/versions/${versionId}`,"历史版本",taskId);applyTaskToWorkspace(task,{save:true,message:"已恢复人工保存的版本"})}catch(error){toast(error.message||"恢复版本失败，当前内容未切换","error")}}
function openHistory(open){el.historyDrawer.classList.toggle("open",open);el.historyDrawer.setAttribute("aria-hidden",String(!open));el.drawerBackdrop.hidden=!open;if(open){refreshHistory();refreshVersions()}}
async function refreshHistory(){const p=await fetch("/api/tasks").then(r=>r.json());el.historyList.replaceChildren();if(!p.tasks?.length){const d=document.createElement("div");d.className="nothing";d.textContent="还没有保存的任务。";return el.historyList.append(d)}p.tasks.forEach(task=>{const item=document.createElement("div");item.className=`history-item ${task.id===state.taskId?"active":""}`;const head=document.createElement("header"),title=document.createElement("strong"),del=document.createElement("button");title.textContent=task.title;del.className="delete-task";del.textContent="删除";del.onclick=async e=>{e.stopPropagation();if(!confirm(`删除“${task.title}”的本地记录、人工版本和专属录音？此操作不可撤销。`))return;const r=await fetch(`/api/tasks/${task.id}`,{method:"DELETE"}),p=await r.json().catch(()=>({}));if(!r.ok)return toast(p.error||"删除任务失败","error");if(task.id===state.taskId)newTask({silent:true});toast(p.audioDeleted?"任务、人工版本和录音已删除":p.audioRetainedShared?"任务和人工版本已删除；录音仍被其他任务使用":"任务和人工版本已删除");refreshHistory()};head.append(title,del);const meta=document.createElement("small");meta.textContent=`${new Date(task.updatedAt).toLocaleString()} · ${task.sourceLength} 字 · ${task.status}`;item.append(head,meta);item.onclick=()=>loadTask(task.id);el.historyList.append(item)})}
async function loadTask(id,{throwOnError=false}={}){try{applyTaskToWorkspace(await fetchTaskJson(`/api/tasks/${id}`,"历史任务",id));return true}catch(error){toast(error.message||"打开历史任务失败","error");if(throwOnError)throw error;return false}}
function newTask({silent=false}={}){state=freshState();activeReviewIndex=-1;activeAudio=null;clearPlaybackHighlight();el.sourceText.value="";el.background.value="";el.glossary.value="";state.terminologyGroupIds=(terminologyLibrary.groups||[]).filter(group=>group.defaultEnabled).map(group=>group.id);state.terminologySnapshot=createTerminologySnapshot(terminologyLibrary,state.terminologyGroupIds);renderTaskTerminologyGroups();el.transcriptionReview.hidden=true;renderReviewAudio();resetResultView();updateStats();queueSave();if(!silent)toast("已新建空白任务")}

