$("#terminologyGroupSelect").onchange=()=>{terminologyEditorGroupId=$("#terminologyGroupSelect").value;renderTerminologyManager()};
$("#terminologyGroupName").onchange=()=>{const group=selectedTermGroup();if(!group)return;group.name=$("#terminologyGroupName").value.trim()||group.name;renderTerminologyManager()};
$("#terminologyGroupDefault").onchange=()=>{const group=selectedTermGroup();if(group)group.defaultEnabled=$("#terminologyGroupDefault").checked};
$("#addTerminologyGroup").onclick=()=>{if(!terminologyDraft)return;const group={id:`group-${crypto.randomUUID()}`,name:`新分组 ${terminologyDraft.groups.length+1}`,defaultEnabled:false,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};terminologyDraft.groups.push(group);terminologyEditorGroupId=group.id;renderTerminologyManager()};
$("#deleteTerminologyGroup").onclick=()=>{const group=selectedTermGroup();if(!group||group.id==="general")return;if(!confirm(`删除“${group.name}”？其中术语会移入“通用术语”。`))return;terminologyDraft.terms.forEach(term=>{if(term.groupId===group.id)term.groupId="general"});terminologyDraft.groups=terminologyDraft.groups.filter(item=>item.id!==group.id);terminologyEditorGroupId="general";renderTerminologyManager()};
$("#addTerminologyTerm").onclick=()=>{const group=selectedTermGroup();if(!group)return;terminologyDraft.terms.push({id:`term-${crypto.randomUUID()}`,canonical:"",aliases:[],category:"",note:"",groupId:group.id,enabled:true,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()});renderTerminologyManager();$("#terminologyTermList .terminology-term-row:last-child input")?.focus()};
$("#exportTerminology").onclick=()=>{if(!terminologyDraft)return;download(JSON.stringify(terminologyDraft,null,2),"json","application/json;charset=utf-8")};
$("#importTerminology").onclick=()=>$("#terminologyImportFile").click();
$("#terminologyImportFile").onchange=async()=>{const file=$("#terminologyImportFile").files[0];if(!file)return;try{const parsed=JSON.parse(await file.text());if(!Array.isArray(parsed.groups)||!Array.isArray(parsed.terms))throw Error("文件缺少 groups 或 terms");terminologyDraft=parsed;terminologyEditorGroupId=parsed.groups[0]?.id||"general";renderTerminologyManager();toast("术语库已导入预览，点击保存设置后生效")}catch(error){toast(error.message||"术语库文件无法读取","error")}finally{$("#terminologyImportFile").value=""}};
