const startupQuery=String(globalThis.location?.search||"");
const startupValue=name=>{const match=startupQuery.match(new RegExp(`(?:^|[?&])${name}=([^&]*)`));return match?decodeURIComponent(match[1].replace(/\+/g," ")):""};
const requestedTaskId=startupValue("task"),requestedTaskSource=startupValue("source");
loadOnlineTranscriptionSettings().then(async()=>{if(requestedTaskId){await loadTask(requestedTaskId,{throwOnError:true});history.replaceState({},"","/");toast(requestedTaskSource==="live"?"实时转写稿已送入人工修订区":"任务已打开")}}).catch(error=>toast(error.message||"初始化失败","error"));
queueSave();
